        elif b[i] < b[i - 1] and b[i] < b[i + 1]:
            events[b[i]] = events.get(b[i], 0) - 1

    # Ordena as alturas dos eventos em ordem decrescente (varredura de cima para baixo)
    sorted_heights = sorted(events.keys(), reverse=True)

    current_components = 0
    max_pieces = 1

    for h in sorted_heights:
        current_components += events[h]
